import copy
from datetime import datetime, timezone
import sqlite3
import unittest
from unittest.mock import patch

import config
import uniclubs_database
import uniclubs_feed


STAMP = '2026-11-15T17:00:00.000000Z'
NEXT_STAMP = '2026-11-15T18:00:00.000000Z'
LATER_STAMP = '2026-11-15T19:00:00.000000Z'
CHECKED = datetime(2026, 11, 15, 20, 0, tzinfo=timezone.utc)
FETCH_TARGET = 'uniclubs_feed.importers.fetch_public_uniclubs_feed'


def public_snapshot(observed=STAMP, **changes):
    """Return a complete valid feed with intentionally nonconsecutive local identities."""
    event = {
        'id': 37, 'external_id': 'event-1', 'club_id': 7, 'title': 'Example workshop',
        'start_utc': '2026-11-16T11:00:00.000000Z',
        'end_utc': '2026-11-16T12:00:00.000000Z',
        'location': 'Online', 'event_type': 'workshop',
        'source_url': 'https://uniclubs.ch/hsg/clubs/example/events/workshop',
        'publication_status': 'published', 'availability_state': 'open',
        'requires_membership': False, 'first_seen_utc': STAMP,
        'last_seen_utc': observed, 'source_missing': False,
    }
    event.update(changes)
    return {'_meta': {'schema_version': 1, 'ai_citation': 'Synthetic test fixture.',
                      'source_url': config.UNICLUBS_EVENTS_URL,
                      'last_success_utc': observed},
            'clubs': [{'id': 7, 'external_id': 'club-1', 'name': 'Example Club',
                       'source_url': 'https://uniclubs.ch/hsg/clubs/example'}],
            'events': [event]}


class UniClubsFeedTests(unittest.TestCase):
    """Exercise pure validation and real SQLite transactions without file or network access."""

    def setUp(self):
        """Initialize only the independent in-memory catalog."""
        self.connection = uniclubs_database.get_connection(':memory:')
        self.addCleanup(self.connection.close)
        uniclubs_database.init_db(self.connection)

    def state(self):
        """Read exact catalog and log rows to detect partial changes or extra commits."""
        return ([tuple(row) for row in self.connection.execute('SELECT * FROM clubs ORDER BY id')],
                [tuple(row) for row in self.connection.execute('SELECT * FROM events ORDER BY id')],
                [tuple(row) for row in self.connection.execute(
                    'SELECT * FROM import_log ORDER BY id')])

    def event(self):
        """Return the first catalog event with the source's stable local ID."""
        return dict(self.connection.execute('SELECT * FROM events WHERE id=37').fetchone())

    def seed(self):
        """Save the initial source observation for update tests."""
        self.assertTrue(uniclubs_feed.apply_public_snapshot(self.connection, public_snapshot()))

    def private_state(self):
        """Attach local plan data and a private event column that feeds must never overwrite."""
        with self.connection:
            self.connection.execute('ALTER TABLE events ADD COLUMN private_note TEXT')
            self.connection.execute('UPDATE events SET private_note=? WHERE id=?',
                                    ('local-only-note', 37))
            self.connection.execute('''CREATE TABLE user_plans (
                event_id INTEGER REFERENCES events(id), owner TEXT, note TEXT)''')
            self.connection.execute('INSERT INTO user_plans VALUES (?, ?, ?)',
                                    (37, 'local-owner', 'local-plan-note'))

    def test_initial_snapshot_keeps_publisher_local_and_external_ids(self):
        """The first feed must preserve its relationship identities and observation times."""
        self.seed()
        row = self.event()
        self.assertEqual((row['id'], row['club_id'], row['external_id']), (37, 7, 'event-1'))
        self.assertEqual(row['first_seen_utc'], STAMP)
        self.assertEqual(uniclubs_feed.get_current_source_success(self.connection), STAMP)

    def test_identical_snapshot_has_no_writes_or_duplicate_success_log(self):
        """The same successful observation must be a true no-op for local data and logs."""
        self.seed()
        before, changes = self.state(), self.connection.total_changes
        self.assertFalse(uniclubs_feed.apply_public_snapshot(self.connection, public_snapshot()))
        self.assertEqual(self.state(), before)
        self.assertEqual(self.connection.total_changes, changes)

    def test_citation_changes_do_not_change_event_observation_semantics(self):
        """Metadata wording alone must not conflict with identical source data and time."""
        self.seed()
        payload = public_snapshot()
        payload['_meta']['ai_citation'] = 'Another nonoperational citation.'
        self.assertFalse(uniclubs_feed.apply_public_snapshot(self.connection, payload))

    def test_new_observation_updates_exact_times_without_replacing_identity(self):
        """A rescheduled event retains its ID and first observation while times change."""
        self.seed()
        payload = public_snapshot(NEXT_STAMP, title='Changed title', location='Square',
                                  start_utc='2026-11-17T11:00:00Z',
                                  end_utc='2026-11-17T14:00:00Z')
        self.assertTrue(uniclubs_feed.apply_public_snapshot(self.connection, payload))
        row = self.event()
        self.assertEqual(row['id'], 37)
        self.assertEqual(row['first_seen_utc'], STAMP)
        self.assertEqual(row['last_seen_utc'], NEXT_STAMP)
        self.assertEqual(row['start_utc'], '2026-11-17T11:00:00.000000Z')
        self.assertEqual(row['title'], 'Changed title')

    def test_public_updates_preserve_private_tables_columns_and_foreign_keys(self):
        """Feed writes must not remove a plan or overwrite a field outside the whitelist."""
        self.seed()
        self.private_state()
        uniclubs_feed.apply_public_snapshot(
            self.connection, public_snapshot(NEXT_STAMP, title='Updated'))
        self.assertEqual(self.event()['private_note'], 'local-only-note')
        row = self.connection.execute('SELECT * FROM user_plans').fetchone()
        self.assertEqual(tuple(row), (37, 'local-owner', 'local-plan-note'))
        self.assertEqual(self.connection.execute('PRAGMA foreign_key_check').fetchall(), [])

    def test_new_historical_records_are_loaded_from_the_full_retained_feed(self):
        """The consumer must not apply the source importer's future-only selection."""
        self.seed()
        payload = public_snapshot(NEXT_STAMP)
        historical = dict(payload['events'][0])
        historical.update(id=92, external_id='historical', title='Historical event',
                          start_utc='2026-11-01T11:00:00Z', end_utc='2026-11-01T12:00:00Z',
                          source_url='https://uniclubs.ch/hsg/clubs/example/events/historical',
                          source_missing=True)
        payload['events'].append(historical)
        uniclubs_feed.apply_public_snapshot(self.connection, payload)
        row = self.connection.execute('SELECT * FROM events WHERE id=92').fetchone()
        self.assertEqual(row['source_missing'], 1)
        self.assertEqual(row['start_utc'], '2026-11-01T11:00:00.000000Z')

    def test_older_snapshot_cannot_roll_back_newer_saved_data(self):
        """An older CDN response must preserve the newer catalog and its successful log."""
        self.seed()
        uniclubs_feed.apply_public_snapshot(
            self.connection, public_snapshot(NEXT_STAMP, title='Newest'))
        before = self.state()
        with self.assertRaises(ValueError):
            uniclubs_feed.apply_public_snapshot(self.connection, public_snapshot())
        self.assertEqual(self.state(), before)

    def test_existing_newer_last_seen_is_protected_without_a_new_success_log(self):
        """Row observations also prevent an old snapshot from overwriting newer metadata."""
        self.seed()
        with self.connection:
            self.connection.execute('UPDATE events SET last_seen_utc=? WHERE id=?',
                                    (NEXT_STAMP, 37))
        before = self.state()
        with self.assertRaises(ValueError):
            uniclubs_feed.apply_public_snapshot(self.connection, public_snapshot())
        self.assertEqual(self.state(), before)

    def test_equal_observation_time_with_conflicting_data_is_rejected(self):
        """A timestamp must not identify two different successful source observations."""
        self.seed()
        before = self.state()
        with self.assertRaises(ValueError):
            uniclubs_feed.apply_public_snapshot(self.connection,
                                                public_snapshot(title='Conflicting title'))
        self.assertEqual(self.state(), before)

    def test_local_and_source_identity_rebinding_is_rejected(self):
        """Neither changed local IDs nor changed external IDs may redirect private references."""
        self.seed()
        before = self.state()
        rebound_event = public_snapshot(NEXT_STAMP, external_id='another-event')
        renumbered_event = public_snapshot(NEXT_STAMP, id=38)
        rebound_club = public_snapshot(NEXT_STAMP)
        rebound_club['clubs'][0]['external_id'] = 'another-club'
        renumbered_club = public_snapshot(NEXT_STAMP)
        renumbered_club['clubs'][0]['id'] = 8
        renumbered_club['events'][0]['club_id'] = 8
        for payload in (rebound_event, renumbered_event, rebound_club, renumbered_club):
            with self.subTest(payload=payload):
                with self.assertRaises(ValueError):
                    uniclubs_feed.apply_public_snapshot(self.connection, payload)
                self.assertEqual(self.state(), before)

    def test_existing_first_observation_cannot_be_rewritten(self):
        """A newer feed must still retain the original first-seen timestamp."""
        self.seed()
        before = self.state()
        with self.assertRaises(ValueError):
            uniclubs_feed.apply_public_snapshot(
                self.connection, public_snapshot(NEXT_STAMP, first_seen_utc=NEXT_STAMP))
        self.assertEqual(self.state(), before)

    def test_missing_and_returning_records_preserve_private_plans(self):
        """Absent rows remain available with a marker and regain the same identity on return."""
        self.seed()
        self.private_state()
        absent = public_snapshot(NEXT_STAMP)
        absent['events'], absent['clubs'] = [], []
        uniclubs_feed.apply_public_snapshot(self.connection, absent)
        self.assertEqual(self.event()['source_missing'], 1)
        self.assertEqual(self.event()['last_seen_utc'], STAMP)
        self.assertFalse(uniclubs_feed.apply_public_snapshot(self.connection, absent))
        uniclubs_feed.apply_public_snapshot(self.connection, public_snapshot(LATER_STAMP))
        self.assertEqual(self.event()['source_missing'], 0)
        self.assertEqual(self.event()['id'], 37)
        self.assertEqual(self.connection.execute(
            'SELECT count(*) FROM user_plans').fetchone()[0], 1)

    def test_invalid_payload_does_not_mutate_catalog(self):
        """Invalid timestamps, flags and relationships must fail before any row changes."""
        self.seed()
        before = self.state()
        invalid = [public_snapshot(NEXT_STAMP, end_utc='bad-time'),
                   public_snapshot(NEXT_STAMP, source_missing='yes'),
                   public_snapshot(NEXT_STAMP, club_id=99)]
        for payload in invalid:
            with self.subTest(payload=payload):
                with self.assertRaises(ValueError):
                    uniclubs_feed.apply_public_snapshot(self.connection, payload)
                self.assertEqual(self.state(), before)

    def test_database_failure_rolls_back_public_updates_and_preserves_private_data(self):
        """An error after real writes must roll back names, events, markers and success logs."""
        self.seed()
        self.private_state()
        with self.connection:
            self.connection.execute('''CREATE TRIGGER reject_applied_feed
                BEFORE INSERT ON import_log
                WHEN NEW.message='Applied public UniClubs snapshot.'
                BEGIN SELECT RAISE(ABORT, 'forced feed failure'); END''')
        before = self.state()
        payload = public_snapshot(NEXT_STAMP, title='Changed before failure')
        payload['clubs'][0]['name'] = 'Changed Club'
        new_event = dict(payload['events'][0])
        new_event.update(id=92, external_id='new-event',
                         source_url='https://uniclubs.ch/hsg/clubs/example/events/new')
        payload['events'].append(new_event)
        with self.assertRaises(sqlite3.IntegrityError):
            uniclubs_feed.apply_public_snapshot(self.connection, payload)
        self.assertEqual(self.state(), before)
        self.assertEqual(self.event()['private_note'], 'local-only-note')
        self.assertEqual(self.connection.execute(
            'SELECT count(*) FROM user_plans').fetchone()[0], 1)

    def test_open_caller_transaction_is_preserved(self):
        """Feed validation must not commit or roll back another operation's pending work."""
        self.connection.execute('''INSERT INTO clubs (id, external_id, name, source_url)
            VALUES (?, ?, ?, ?)''',
                                (99, 'pending', 'Pending',
                                 'https://uniclubs.ch/hsg/clubs/pending'))
        with self.assertRaises(ValueError):
            uniclubs_feed.apply_public_snapshot(self.connection, public_snapshot())
        self.assertTrue(self.connection.in_transaction)
        self.assertEqual(self.connection.execute('SELECT count(*) FROM clubs').fetchone()[0], 1)

    def test_fetch_status_separates_publisher_time_from_local_check(self):
        """The UI must distinguish a recent HTTP check from the publisher's source freshness."""
        with patch(FETCH_TARGET, return_value=public_snapshot(), create=True):
            status = uniclubs_feed.fetch_and_apply(self.connection, now=CHECKED)
        self.assertTrue(status['ok'])
        self.assertTrue(status['changed'])
        self.assertEqual(status['source_success_utc'], STAMP)
        self.assertEqual(status['checked_at_utc'], '2026-11-15T20:00:00.000000Z')

    def test_download_failure_retains_catalog_and_sanitizes_error_status(self):
        """Raw transport details must not enter visible messages or the import log."""
        self.seed()
        old = self.event()
        with patch(FETCH_TARGET, side_effect=ValueError('private-secret-marker'), create=True):
            status = uniclubs_feed.fetch_and_apply(self.connection, now=CHECKED)
        self.assertFalse(status['ok'])
        self.assertFalse(status['changed'])
        self.assertEqual(self.event(), old)
        self.assertNotIn('private-secret-marker', status['message'])
        log = uniclubs_database.get_import_log(self.connection)[0]
        self.assertEqual(log['status'], 'error')
        self.assertNotIn('private-secret-marker', log['message'])

    def test_older_download_keeps_newer_source_time_and_explains_status(self):
        """A valid but old feed response must not report the newer local catalog as changed."""
        self.seed()
        uniclubs_feed.apply_public_snapshot(self.connection, public_snapshot(NEXT_STAMP))
        with patch(FETCH_TARGET, return_value=public_snapshot(), create=True):
            status = uniclubs_feed.fetch_and_apply(self.connection, now=CHECKED)
        self.assertFalse(status['ok'])
        self.assertFalse(status['changed'])
        self.assertEqual(status['source_success_utc'], NEXT_STAMP)
        self.assertIn('older', status['message'])

    def test_fetch_refuses_open_transaction_before_network_and_logging(self):
        """A caller's pending insert remains pending and no HTTP operation is attempted."""
        self.connection.execute('''INSERT INTO clubs (id, external_id, name, source_url)
            VALUES (?, ?, ?, ?)''',
                                (99, 'pending', 'Pending',
                                 'https://uniclubs.ch/hsg/clubs/pending'))
        with patch(FETCH_TARGET, create=True) as fetch:
            status = uniclubs_feed.fetch_and_apply(self.connection, now=CHECKED)
        fetch.assert_not_called()
        self.assertFalse(status['ok'])
        self.assertTrue(self.connection.in_transaction)
        self.assertEqual(uniclubs_database.get_import_log(self.connection), [])


if __name__ == '__main__':
    unittest.main()
